// Basic Animations Module JavaScript

// Module definition
window.BasicAnimations = {
    name: 'Basic Animations',

    init: function() {
        const boxes = document.querySelectorAll('#basic-animations-demo .tween-box');

        // Reset all boxes
        gsap.set(boxes, { 
            scale: 1, 
            rotation: 0, 
            x: 0, 
            y: 0,
            backgroundColor: '#00ff88'
        });

        // Add animating class to prevent interaction during animation
        boxes.forEach(box => box.classList.add('animating'));

        // Scale animation
        if (boxes[0]) {
            gsap.to(boxes[0], {
                scale: 1.5,
                duration: 1,
                ease: "bounce.out",
                yoyo: true,
                repeat: 1,
                onComplete: () => {
                    boxes[0].classList.remove('animating');
                }
            });
        }

        // Rotation animation
        if (boxes[1]) {
            gsap.to(boxes[1], {
                rotation: 360,
                duration: 1,
                ease: "power2.inOut",
                delay: 0.2,
                onComplete: () => {
                    boxes[1].classList.remove('animating');
                }
            });
        }

        // Movement animation
        if (boxes[2]) {
            gsap.to(boxes[2], {
                x: 50,
                y: -30,
                duration: 1,
                ease: "elastic.out(1, 0.3)",
                delay: 0.4,
                yoyo: true,
                repeat: 1,
                onComplete: () => {
                    boxes[2].classList.remove('animating');
                }
            });
        }

        console.log('Basic Animations module loaded');
    },

    // Reset function
    reset: function() {
        const boxes = document.querySelectorAll('#basic-animations-demo .tween-box');
        gsap.killTweensOf(boxes);
        gsap.set(boxes, { 
            scale: 1, 
            rotation: 0, 
            x: 0, 
            y: 0,
            backgroundColor: '#00ff88'
        });
        boxes.forEach(box => box.classList.remove('animating'));
    }
};

// Auto-register module
if (typeof window.GSAPModules === 'undefined') {
    window.GSAPModules = {};
}
window.GSAPModules['basic-animations'] = window.BasicAnimations;

// Card Reveals Module JavaScript

// Module definition
window.CardReveals = {
    name: 'Card Reveals',
    scrollTriggerInstance: null,

    init: function() {
        // Register ScrollTrigger plugin
        gsap.registerPlugin(ScrollTrigger);

        const cards = document.querySelectorAll('#card-reveals-demo .card');
        if (!cards.length) return;

        // Reset cards
        gsap.set(cards, {
            y: 50,
            opacity: 0,
            scale: 0.8
        });

        cards.forEach(card => {
            card.classList.remove('revealed', 'animating');
        });

        // Create reveal animation
        this.scrollTriggerInstance = gsap.to(cards, {
            y: 0,
            opacity: 1,
            scale: 1,
            duration: 0.8,
            ease: "back.out(1.7)",
            stagger: 0.2,
            scrollTrigger: {
                trigger: cards[0],
                start: "top 80%",
                toggleActions: "play none none reverse",
                onEnter: () => {
                    cards.forEach((card, index) => {
                        setTimeout(() => {
                            card.classList.add('revealed');
                        }, index * 200);
                    });
                },
                onLeave: () => {
                    cards.forEach(card => {
                        card.classList.remove('revealed');
                    });
                },
                onEnterBack: () => {
                    cards.forEach((card, index) => {
                        setTimeout(() => {
                            card.classList.add('revealed');
                        }, index * 200);
                    });
                },
                onLeaveBack: () => {
                    cards.forEach(card => {
                        card.classList.remove('revealed');
                    });
                }
            },
            onStart: () => {
                cards.forEach(card => card.classList.add('animating'));
            },
            onComplete: () => {
                cards.forEach(card => card.classList.remove('animating'));
            }
        });

        // Add individual hover effects
        cards.forEach((card, index) => {
            card.addEventListener('click', () => {
                if (!card.classList.contains('animating')) {
                    gsap.to(card, {
                        scale: 0.95,
                        duration: 0.1,
                        yoyo: true,
                        repeat: 1,
                        ease: "power2.out",
                        onComplete: () => {
                            gsap.to(card, {
                                rotation: 360,
                                duration: 0.6,
                                ease: "power2.out"
                            });
                        }
                    });
                }
            });
        });

        console.log('Card Reveals module loaded');
    },

    // Reset function
    reset: function() {
        const cards = document.querySelectorAll('#card-reveals-demo .card');

        // Kill ScrollTrigger instance
        if (this.scrollTriggerInstance) {
            this.scrollTriggerInstance.kill();
            this.scrollTriggerInstance = null;
        }

        // Reset cards
        gsap.killTweensOf(cards);
        gsap.set(cards, {
            y: 0,
            opacity: 1,
            scale: 1,
            rotation: 0
        });

        cards.forEach(card => {
            card.classList.remove('revealed', 'animating');
        });

        // Refresh ScrollTrigger
        ScrollTrigger.refresh();
    }
};

// Auto-register module
if (typeof window.GSAPModules === 'undefined') {
    window.GSAPModules = {};
}
window.GSAPModules['card-reveals'] = window.CardReveals;

// Hover Interactions Module JavaScript

// Module definition
window.HoverInteractions = {
    name: 'Hover Interactions',

    init: function() {
        const hoverBoxes = document.querySelectorAll('#hover-interactions-demo .hover-box');
        if (!hoverBoxes.length) return;

        // Reset boxes
        gsap.set(hoverBoxes, {
            scale: 1,
            rotation: 0,
            backgroundColor: "#4ecdc4"
        });

        hoverBoxes.forEach(box => {
            box.classList.remove('animating');
        });

        // Setup hover effects for each box
        hoverBoxes.forEach((box, index) => {
            if (index === 0) {
                // First box: Hover effects
                box.addEventListener('mouseenter', () => {
                    if (!box.classList.contains('animating')) {
                        gsap.to(box, {
                            scale: 1.2,
                            rotation: 15,
                            backgroundColor: "#ff6b6b",
                            duration: 0.3,
                            ease: "back.out(1.7)"
                        });
                    }
                });

                box.addEventListener('mouseleave', () => {
                    if (!box.classList.contains('animating')) {
                        gsap.to(box, {
                            scale: 1,
                            rotation: 0,
                            backgroundColor: "#4ecdc4",
                            duration: 0.3,
                            ease: "power2.out"
                        });
                    }
                });
            } else {
                // Second box: Click effects
                box.addEventListener('click', () => {
                    if (!box.classList.contains('animating')) {
                        box.classList.add('animating');

                        gsap.to(box, {
                            scale: 0.8,
                            duration: 0.1,
                            ease: "power2.out",
                            yoyo: true,
                            repeat: 1,
                            onComplete: () => {
                                gsap.to(box, {
                                    rotation: "+=360",
                                    backgroundColor: "#00ff88",
                                    duration: 0.5,
                                    ease: "power2.out",
                                    onComplete: () => {
                                        gsap.to(box, {
                                            backgroundColor: "#4ecdc4",
                                            duration: 0.3,
                                            delay: 0.2,
                                            onComplete: () => {
                                                box.classList.remove('animating');
                                            }
                                        });
                                    }
                                });
                            }
                        });
                    }
                });

                // Hover effect for click box
                box.addEventListener('mouseenter', () => {
                    if (!box.classList.contains('animating')) {
                        gsap.to(box, {
                            scale: 1.1,
                            duration: 0.3,
                            ease: "power2.out"
                        });
                    }
                });

                box.addEventListener('mouseleave', () => {
                    if (!box.classList.contains('animating')) {
                        gsap.to(box, {
                            scale: 1,
                            duration: 0.3,
                            ease: "power2.out"
                        });
                    }
                });
            }
        });

        console.log('Hover Interactions module loaded');
    },

    // Reset function
    reset: function() {
        const hoverBoxes = document.querySelectorAll('#hover-interactions-demo .hover-box');

        gsap.killTweensOf(hoverBoxes);
        gsap.set(hoverBoxes, {
            scale: 1,
            rotation: 0,
            backgroundColor: "#4ecdc4"
        });

        hoverBoxes.forEach(box => {
            box.classList.remove('animating');
        });
    }
};

// Auto-register module
if (typeof window.GSAPModules === 'undefined') {
    window.GSAPModules = {};
}
window.GSAPModules['hover-interactions'] = window.HoverInteractions;

