// Mouse Follow Module JavaScript

// Module definition
window.MouseFollow = {
    name: 'Mouse Follow',

    init: function() {
        const mouseArea = document.querySelector('#mouse-follow-demo .mouse-follow-area');
        const follower = document.querySelector('#mouse-follow-demo .follower');

        if (!mouseArea || !follower) {
            console.warn('Mouse Follow: Required elements not found');
            return;
        }

        // Reset follower
        gsap.set(follower, {
            x: 0,
            y: 0,
            scale: 0,
            opacity: 0
        });

        // Mouse move handler
        const handleMouseMove = (e) => {
            const rect = mouseArea.getBoundingClientRect();
            const x = e.clientX - rect.left;
            const y = e.clientY - rect.top;

            gsap.to(follower, {
                x: x - 10,
                y: y - 10,
                duration: 0.3,
                ease: "power2.out"
            });
        };

        // Mouse enter handler
        const handleMouseEnter = () => {
            gsap.to(follower, {
                scale: 1,
                opacity: 1,
                duration: 0.3,
                ease: "back.out(1.7)"
            });
        };

        // Mouse leave handler
        const handleMouseLeave = () => {
            gsap.to(follower, {
                scale: 0,
                opacity: 0,
                duration: 0.3,
                ease: "power2.out"
            });
        };

        // Add event listeners
        mouseArea.addEventListener('mousemove', handleMouseMove);
        mouseArea.addEventListener('mouseenter', handleMouseEnter);
        mouseArea.addEventListener('mouseleave', handleMouseLeave);

        console.log('Mouse Follow module loaded');
    },

    // Reset function
    reset: function() {
        const mouseArea = document.querySelector('#mouse-follow-demo .mouse-follow-area');
        const follower = document.querySelector('#mouse-follow-demo .follower');

        if (mouseArea && follower) {
            // Remove event listeners
            mouseArea.removeEventListener('mousemove', this.handleMouseMove);
            mouseArea.removeEventListener('mouseenter', this.handleMouseEnter);
            mouseArea.removeEventListener('mouseleave', this.handleMouseLeave);

            // Reset follower
            gsap.killTweensOf(follower);
            gsap.set(follower, {
                x: 0,
                y: 0,
                scale: 0,
                opacity: 0
            });
        }
    }
};

// Auto-register module
if (typeof window.GSAPModules === 'undefined') {
    window.GSAPModules = {};
}
window.GSAPModules['mouse-follow'] = window.MouseFollow;

// Parallax Effects Module JavaScript

// Module definition
window.ParallaxEffects = {
    name: 'Parallax Effects',
    scrollTriggerInstances: [],

    init: function() {
        // Register ScrollTrigger plugin
        gsap.registerPlugin(ScrollTrigger);

        const parallaxBg = document.querySelector('#parallax-effects-demo .parallax-bg');
        const parallaxContent = document.querySelector('#parallax-effects-demo .parallax-content');
        const parallaxContainer = document.querySelector('#parallax-effects-demo .parallax-container');

        if (!parallaxBg || !parallaxContent || !parallaxContainer) return;

        // Reset elements
        gsap.set(parallaxBg, { yPercent: 0 });
        gsap.set(parallaxContent, { y: 0, opacity: 1 });

        parallaxContainer.classList.add('animating');

        // Parallax background effect
        const bgAnimation = gsap.to(parallaxBg, {
            yPercent: -50,
            ease: "none",
            scrollTrigger: {
                trigger: parallaxContainer,
                start: "top bottom",
                end: "bottom top",
                scrub: true,
                refreshPriority: -1
            }
        });

        this.scrollTriggerInstances.push(bgAnimation);

        // Content reveal animation
        const contentAnimation = gsap.fromTo(parallaxContent, {
            y: 50,
            opacity: 0
        }, {
            y: 0,
            opacity: 1,
            duration: 1,
            ease: "power2.out",
            scrollTrigger: {
                trigger: parallaxContent,
                start: "top 70%",
                toggleActions: "play none none reverse"
            }
        });

        this.scrollTriggerInstances.push(contentAnimation);

        // Add extra visual effects
        gsap.to(parallaxContainer, {
            boxShadow: "0 12px 35px rgba(0, 0, 0, 0.3)",
            duration: 2,
            ease: "power2.out",
            scrollTrigger: {
                trigger: parallaxContainer,
                start: "top 80%",
                toggleActions: "play none none reverse"
            }
        });

        console.log('Parallax Effects module loaded');
    },

    // Reset function
    reset: function() {
        const parallaxBg = document.querySelector('#parallax-effects-demo .parallax-bg');
        const parallaxContent = document.querySelector('#parallax-effects-demo .parallax-content');
        const parallaxContainer = document.querySelector('#parallax-effects-demo .parallax-container');

        // Kill all ScrollTrigger instances
        this.scrollTriggerInstances.forEach(instance => {
            if (instance && instance.kill) {
                instance.kill();
            }
        });
        this.scrollTriggerInstances = [];

        if (parallaxBg && parallaxContent && parallaxContainer) {
            // Reset elements
            gsap.set(parallaxBg, { yPercent: 0 });
            gsap.set(parallaxContent, { y: 0, opacity: 1 });
            gsap.set(parallaxContainer, { boxShadow: "0 8px 25px rgba(0, 0, 0, 0.2)" });

            parallaxContainer.classList.remove('animating');
        }

        // Refresh ScrollTrigger
        ScrollTrigger.refresh();
    }
};

// Auto-register module
if (typeof window.GSAPModules === 'undefined') {
    window.GSAPModules = {};
}
window.GSAPModules['parallax-effects'] = window.ParallaxEffects;

// ScrollTrigger Module JavaScript

// Module definition
window.ScrollTriggerModule = {
    name: 'ScrollTrigger',
    scrollTriggerInstance: null,

    init: function() {
        // Register ScrollTrigger plugin
        gsap.registerPlugin(ScrollTrigger);

        const scrollBox = document.querySelector('#scroll-trigger-demo .scroll-box');
        if (!scrollBox) return;

        // Reset the box
        gsap.set(scrollBox, {
            scale: 0.5,
            rotation: 0,
            backgroundColor: "#ff6b6b"
        });

        scrollBox.classList.remove('triggered');

        // Create ScrollTrigger animation
        this.scrollTriggerInstance = gsap.fromTo(scrollBox, {
            scale: 0.5,
            rotation: 0,
            backgroundColor: "#ff6b6b"
        }, {
            scale: 1.2,
            rotation: 360,
            backgroundColor: "#00ff88",
            duration: 1,
            ease: "back.out(1.7)",
            scrollTrigger: {
                trigger: scrollBox,
                start: "top 80%",
                end: "bottom 20%",
                scrub: 1,
                toggleActions: "play none none reverse",
                onEnter: () => {
                    scrollBox.classList.add('triggered');
                },
                onLeave: () => {
                    scrollBox.classList.remove('triggered');
                },
                onEnterBack: () => {
                    scrollBox.classList.add('triggered');
                },
                onLeaveBack: () => {
                    scrollBox.classList.remove('triggered');
                },
                // Add markers for debugging (remove in production)
                // markers: true
            }
        });

        console.log('ScrollTrigger module loaded');
    },

    // Reset function
    reset: function() {
        const scrollBox = document.querySelector('#scroll-trigger-demo .scroll-box');
        if (!scrollBox) return;

        // Kill existing ScrollTrigger
        if (this.scrollTriggerInstance) {
            this.scrollTriggerInstance.kill();
            this.scrollTriggerInstance = null;
        }

        // Reset the box
        gsap.set(scrollBox, {
            scale: 1,
            rotation: 0,
            backgroundColor: "#ff6b6b"
        });

        scrollBox.classList.remove('triggered');

        // Refresh ScrollTrigger
        ScrollTrigger.refresh();
    }
};

// Auto-register module
if (typeof window.GSAPModules === 'undefined') {
    window.GSAPModules = {};
}
