// Shape Morphing Module JavaScript

// Module definition
window.ShapeMorphing = {
    name: 'Shape Morphing',

    init: function() {
        const morphShape = document.querySelector('#shape-morphing-demo .morph-shape');

        if (!morphShape) {
            console.warn('Shape Morphing: Required elements not found');
            return;
        }

        // Add animating class
        morphShape.classList.add('animating');

        const shapes = [
            "M100,50 L150,150 L50,150 Z", // Triangle
            "M50,100 Q100,50 150,100 Q100,150 50,100", // Diamond-like
            "M100,50 A50,50 0 1,1 100,150 A50,50 0 1,1 100,50", // Circle
            "M50,75 L150,75 L150,125 L50,125 Z", // Rectangle
            "M100,50 L150,150 L50,150 Z" // Back to triangle
        ];

        const colors = ["#00ff88", "#ff6b6b", "#4ecdc4", "#8B5CF6", "#00ff88"];

        const tl = gsap.timeline({
            onComplete: () => {
                morphShape.classList.remove('animating');
            }
        });

        shapes.forEach((shape, index) => {
            tl.to(morphShape, {
                attr: { d: shape },
                fill: colors[index],
                duration: 1,
                ease: "power2.inOut"
            }, index * 1.2);
        });

        console.log('Shape Morphing module loaded');
    },

    // Reset function
    reset: function() {
        const morphShape = document.querySelector('#shape-morphing-demo .morph-shape');

        if (morphShape) {
            gsap.killTweensOf(morphShape);
            gsap.set(morphShape, {
                attr: { d: "M100,50 L150,150 L50,150 Z" },
                fill: "#00ff88"
            });
            morphShape.classList.remove('animating');
        }
    }
};

// Auto-register module
if (typeof window.GSAPModules === 'undefined') {
    window.GSAPModules = {};
}
window.GSAPModules['shape-morphing'] = window.ShapeMorphing;

// SVG Path Animation Module JavaScript

// Module definition
window.SvgPath = {
    name: 'SVG Path Animation',

    init: function() {
        // Check if MotionPathPlugin is available
        if (typeof MotionPathPlugin === 'undefined') {
            console.warn('SVG Path: MotionPathPlugin not available, using fallback animation');
            this.initFallback();
            return;
        }

        gsap.registerPlugin(MotionPathPlugin);

        const pathFollower = document.querySelector('#svg-path-demo .path-follower');
        const motionPath = document.querySelector('#svg-path-demo .motion-path');

        if (!pathFollower || !motionPath) {
            console.warn('SVG Path: Required elements not found');
            return;
        }

        // Add animating class
        pathFollower.classList.add('animating');

        // Reset position
        gsap.set(pathFollower, { 
            motionPath: { path: motionPath, start: 0 }
        });

        // Animate along path
        gsap.to(pathFollower, {
            motionPath: {
                path: motionPath,
                align: motionPath,
                alignOrigin: [0.5, 0.5],
                autoRotate: true
            },
            duration: 3,
            ease: "power2.inOut",
            repeat: 1,
            yoyo: true,
            onComplete: () => {
                pathFollower.classList.remove('animating');
            }
        });

        // Add scale animation
        gsap.to(pathFollower, {
            scale: 1.5,
            duration: 1.5,
            ease: "sine.inOut",
            repeat: 1,
            yoyo: true
        });

        console.log('SVG Path module loaded');
    },

    // Fallback animation without MotionPathPlugin
    initFallback: function() {
        const pathFollower = document.querySelector('#svg-path-demo .path-follower');

        if (!pathFollower) return;

        // Simple circular motion as fallback
        gsap.to(pathFollower, {
            rotation: 360,
            transformOrigin: "150px 100px",
            duration: 3,
            ease: "power2.inOut",
            repeat: 1,
            yoyo: true
        });

        gsap.to(pathFollower, {
            scale: 1.5,
            duration: 1.5,
            ease: "sine.inOut",
            repeat: 1,
            yoyo: true
        });
    },

    // Reset function
    reset: function() {
        const pathFollower = document.querySelector('#svg-path-demo .path-follower');

        if (pathFollower) {
            gsap.killTweensOf(pathFollower);
            gsap.set(pathFollower, {
                x: 0,
                y: 0,
                rotation: 0,
                scale: 1
            });
            pathFollower.classList.remove('animating');
        }
    }
};

// Auto-register module
if (typeof window.GSAPModules === 'undefined') {
    window.GSAPModules = {};
}
window.GSAPModules['svg-path'] = window.SvgPath;

// Text Animations Module JavaScript

// Module definition
window.TextAnimations = {
    name: 'Text Animations',
    originalText: 'Hello GSAP World!',

    init: function() {
        const textElement = document.querySelector('#text-animations-demo .animated-text');
        if (!textElement) return;

        // Store original text if not already stored
        if (!this.originalText) {
            this.originalText = textElement.textContent;
        }

        const text = this.originalText;
        const chars = text.split('');

        // Split text into spans
        textElement.innerHTML = chars.map(char => 
            char === ' ' ? '&nbsp;' : `<span class="char">${char}</span>`
        ).join('');

        const charElements = textElement.querySelectorAll('.char');

        // Add animating class
        textElement.classList.add('animating');

        // Animate characters entrance
        gsap.fromTo(charElements, {
            opacity: 0,
            y: 50,
            rotation: 180,
            scale: 0
        }, {
            opacity: 1,
            y: 0,
            rotation: 0,
            scale: 1,
            duration: 0.8,
            ease: "back.out(1.7)",
            stagger: 0.05,
            onComplete: () => {
                // Color wave animation
                gsap.to(charElements, {
                    color: "#00ff88",
                    duration: 0.3,
                    stagger: 0.05,
                    yoyo: true,
                    repeat: 1,
                    onComplete: () => {
                        // Bounce effect
                        gsap.to(charElements, {
                            y: -10,
                            duration: 0.2,
                            stagger: 0.03,
                            yoyo: true,
                            repeat: 1,
                            ease: "power2.out",
                            onComplete: () => {
                                textElement.classList.remove('animating');
                            }
                        });
                    }
                });
            }
        });

        console.log('Text Animations module loaded');
    },

    // Reset function
    reset: function() {
        const textElement = document.querySelector('#text-animations-demo .animated-text');
        if (!textElement) return;

        gsap.killTweensOf(textElement.querySelectorAll('.char'));
        textElement.textContent = this.originalText;
        textElement.classList.remove('animating');
    }
};

// Auto-register module
if (typeof window.GSAPModules === 'undefined') {
    window.GSAPModules = {};
}
window.GSAPModules['text-animations'] = window.TextAnimations;

// Timeline Sequences Module JavaScript

// Module definition
window.TimelineSequences = {
    name: 'Timeline Sequences',

    init: function() {
        const boxes = document.querySelectorAll('#timeline-sequences-demo .timeline-box');
        const tl = gsap.timeline({
            onComplete: () => {
                boxes.forEach(box => box.classList.remove('animating'));
            }
        });

        // Reset positions
        gsap.set(boxes, { 
            scale: 1, 
            rotation: 0, 
            y: 0, 
            opacity: 1,
            backgroundColor: '#ff6b6b'
        });

        // Add animating class
        boxes.forEach(box => box.classList.add('animating'));

        // Create timeline sequence
        tl.from(boxes[0], {
            scale: 0,
            rotation: 180,
            duration: 0.5,
            ease: "back.out(1.7)"
        })
        .from(boxes[1], {
            y: -100,
            opacity: 0,
            duration: 0.5,
            ease: "bounce.out"
        }, "-=0.3")
        .from(boxes[2], {
            scale: 0,
            rotation: -180,
            duration: 0.5,
            ease: "back.out(1.7)"
        }, "-=0.3")
        .from(boxes[3], {
            y: 100,
            opacity: 0,
            duration: 0.5,
            ease: "bounce.out"
        }, "-=0.3")
        .to(boxes, {
            rotation: 360,
            duration: 1,
            ease: "power2.inOut",
            stagger: 0.1
        }, "+=0.5")
        .to(boxes, {
            backgroundColor: "#00ff88",
            duration: 0.5,
            stagger: 0.1
        }, "-=0.5")
        .to(boxes, {
            backgroundColor: "#ff6b6b",
            duration: 0.5,
            stagger: 0.1
        });

        console.log('Timeline Sequences module loaded');
    },

    // Reset function
    reset: function() {
        const boxes = document.querySelectorAll('#timeline-sequences-demo .timeline-box');
        gsap.killTweensOf(boxes);
        gsap.set(boxes, { 
            scale: 1, 
            rotation: 0, 
            y: 0, 
            opacity: 1,
            backgroundColor: '#ff6b6b'
        });
        boxes.forEach(box => box.classList.remove('animating'));
    }
};

// Auto-register module
if (typeof window.GSAPModules === 'undefined') {
    window.GSAPModules = {};
}
window.GSAPModules['timeline-sequences'] = window.TimelineSequences;

"use client";

import { useRef, useState } from "react";
import { gsap } from "gsap";
import { MotionPathPlugin } from "gsap/MotionPathPlugin";

// Register MotionPath plugin
if (typeof window !== "undefined") {
  gsap.registerPlugin(MotionPathPlugin);
}

const AdvancedAnimations = () => {
  const pathFollowerRef = useRef<SVGCircleElement>(null);
  const morphShapeRef = useRef<SVGPathElement>(null);
  const loaderDotsRef = useRef<HTMLDivElement[]>([]);
  const [isLoaderActive, setIsLoaderActive] = useState(false);

  const addToLoaderRefs = (el: HTMLDivElement | null, index: number) => {
    if (el) {
      loaderDotsRef.current[index] = el;
    }
  };

  const playPathAnimation = () => {
    if (pathFollowerRef.current) {
      // Reset position
      gsap.set(pathFollowerRef.current, {
        motionPath: { path: "#motion-path", start: 0 },
      });

      // Animate along path
      gsap.to(pathFollowerRef.current, {
        motionPath: {
          path: "#motion-path",
          align: "#motion-path",
          alignOrigin: [0.5, 0.5],
          autoRotate: true,
        },
        duration: 3,
        ease: "power2.inOut",
        repeat: 1,
        yoyo: true,
      });

      // Add scale animation
      gsap.to(pathFollowerRef.current, {
        scale: 1.5,
        duration: 1.5,
        ease: "sine.inOut",
        repeat: 1,
        yoyo: true,
      });
    }
  };

  const playMorphAnimation = () => {
    if (morphShapeRef.current) {
      const shapes = [
        "M100,50 L150,150 L50,150 Z", // Triangle
        "M50,100 Q100,50 150,100 Q100,150 50,100", // Diamond-like
        "M100,50 A50,50 0 1,1 100,150 A50,50 0 1,1 100,50", // Circle
        "M50,75 L150,75 L150,125 L50,125 Z", // Rectangle
        "M100,50 L150,150 L50,150 Z", // Back to triangle
      ];

      const colors = ["#10B981", "#EF4444", "#06B6D4", "#8B5CF6", "#10B981"];

      const tl = gsap.timeline();

      shapes.forEach((shape, index) => {
        tl.to(
          morphShapeRef.current,
          {
            attr: { d: shape },
            fill: colors[index],
            duration: 1,
            ease: "power2.inOut",
          },
          index * 1.2
        );
      });
    }
  };

  const toggleLoader = () => {
    if (!isLoaderActive) {
      startLoader();
    } else {
      stopLoader();
    }
    setIsLoaderActive(!isLoaderActive);
  };

  const startLoader = () => {
    // Pulsing animation
    gsap.to(loaderDotsRef.current, {
      scale: 1.5,
      backgroundColor: "#EF4444",
      duration: 0.6,
      ease: "power2.inOut",
      stagger: 0.2,
      repeat: -1,
      yoyo: true,
    });
  };

  const stopLoader = () => {
    gsap.killTweensOf(loaderDotsRef.current);

    gsap.to(loaderDotsRef.current, {
      scale: 1,
      backgroundColor: "#10B981",
      duration: 0.3,
      ease: "power2.out",
    });
  };

  return (
    <section id="advanced" className="py-20 min-h-screen">
      <div className="max-w-6xl mx-auto px-6">
        <h2 className="text-4xl font-bold text-white text-center mb-16">
          Advanced Animations
        </h2>

        {/* SVG Path Animation */}
        <div className="mb-16 bg-white bg-opacity-10 rounded-2xl p-8 backdrop-blur-sm">
          <h3 className="text-2xl font-semibold text-white mb-6">
            SVG Path Animation
          </h3>
          <div className="flex justify-center items-center mb-8 min-h-[200px] bg-black bg-opacity-20 rounded-xl p-8">
            <svg
              width="300"
              height="200"
              viewBox="0 0 300 200"
              className="overflow-visible cursor-pointer"
              onClick={playPathAnimation}
            >
              <path
                id="motion-path"
                d="M50,100 Q150,50 250,100"
                stroke="#10B981"
                strokeWidth="2"
                fill="none"
              />
              <circle ref={pathFollowerRef} r="8" fill="#EF4444" />
            </svg>
          </div>
        </div>

        {/* Morphing Animation */}
        <div className="mb-16 bg-white bg-opacity-10 rounded-2xl p-8 backdrop-blur-sm">
          <h3 className="text-2xl font-semibold text-white mb-6">
            Morphing Animation
          </h3>
          <div className="flex justify-center items-center mb-8 min-h-[200px] bg-black bg-opacity-20 rounded-xl p-8">
            <svg width="200" height="200" viewBox="0 0 200 200">
              <path
                ref={morphShapeRef}
                d="M100,50 L150,150 L50,150 Z"
                fill="#10B981"
              />
            </svg>
          </div>
          <button
            onClick={playMorphAnimation}
            className="bg-gradient-to-r from-purple-500 to-blue-500 text-white px-6 py-3 rounded-full font-medium hover:scale-105 transition-transform"
          >
            Morph Shape
          </button>
        </div>

        {/* Loading Animation */}
        <div className="bg-white bg-opacity-10 rounded-2xl p-8 backdrop-blur-sm">
          <h3 className="text-2xl font-semibold text-white mb-6">
            Loading Animation
          </h3>
          <div
            className="flex justify-center items-center mb-8 min-h-[200px] bg-black bg-opacity-20 rounded-xl p-8 cursor-pointer"
            onClick={toggleLoader}
          >
            <div className="flex gap-3">
              {[0, 1, 2].map((index) => (
                <div
                  key={index}
                  ref={(el) => addToLoaderRefs(el, index)}
                  className="w-5 h-5 bg-green-400 rounded-full"
                />
              ))}
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default AdvancedAnimations;

"use client";

import { useRef } from "react";
import {
  useBasicAnimations,
  useTextAnimation,
  useTimelineSequence,
} from "@/hooks/useGSAP";

interface BasicAnimationsProps {
  variant?: "full" | "module";
}

const BasicAnimations = ({ variant = "full" }: BasicAnimationsProps) => {
  // Refs for different animation groups
  const tweenBoxesRef = useRef<HTMLDivElement[]>([]);
  const timelineBoxesRef = useRef<HTMLDivElement[]>([]);
  const textRef = useRef<HTMLHeadingElement>(null);

  // Custom hooks
  const { scaleAnimation, rotateAnimation, moveAnimation, resetAll } =
    useBasicAnimations();
  const { splitTextAnimation, colorWaveAnimation } = useTextAnimation();
  const { createSequence } = useTimelineSequence();

  // Helper functions for refs
  const addToTweenRefs = (el: HTMLDivElement | null, index: number) => {
    if (el) {
      tweenBoxesRef.current[index] = el;
    }
  };

  const addToTimelineRefs = (el: HTMLDivElement | null, index: number) => {
    if (el) {
      timelineBoxesRef.current[index] = el;
    }
  };

  // Animation handlers
  const playBasicTweens = () => {
    console.log("playBasicTweens called");
    console.log("tweenBoxesRef.current:", tweenBoxesRef.current);

    resetAll(tweenBoxesRef.current);

    // Scale animation
    if (tweenBoxesRef.current[0]) {
      console.log("Starting scale animation");
      scaleAnimation(tweenBoxesRef.current[0]);
    }

    // Rotation animation
    if (tweenBoxesRef.current[1]) {
      console.log("Starting rotation animation");
      rotateAnimation(tweenBoxesRef.current[1], { delay: 0.2 });
    }

    // Movement animation
    if (tweenBoxesRef.current[2]) {
      console.log("Starting movement animation");
      moveAnimation(tweenBoxesRef.current[2], {
        x: variant === "module" ? 50 : 100,
        y: variant === "module" ? -30 : -50,
        delay: 0.4,
      });
    }
  };

  const playTimeline = () => {
    createSequence(timelineBoxesRef.current.filter(Boolean));
  };

  const playTextAnimation = () => {
    if (textRef.current) {
      splitTextAnimation(textRef.current);

      // Add color wave effect
      setTimeout(() => {
        colorWaveAnimation(textRef.current!, { delay: 1 });
      }, 1000);
    }
  };

  // Module variant (simplified)
  if (variant === "module") {
    return (
      <div
        className="flex gap-4 justify-center items-center cursor-pointer"
        onClick={playBasicTweens}
      >
        <div
          ref={(el) => addToTweenRefs(el, 0)}
          className="w-20 h-20 bg-green-400 rounded-lg flex items-center justify-center text-gray-800 font-bold transition-colors"
        >
          Scale
        </div>
        <div
          ref={(el) => addToTweenRefs(el, 1)}
          className="w-20 h-20 bg-green-400 rounded-lg flex items-center justify-center text-gray-800 font-bold transition-colors"
        >
          Rotate
        </div>
        <div
          ref={(el) => addToTweenRefs(el, 2)}
          className="w-20 h-20 bg-green-400 rounded-lg flex items-center justify-center text-gray-800 font-bold transition-colors"
        >
          Move
        </div>
      </div>
    );
  }

  // Full variant (complete page section)
  return (
    <section id="basic" className="py-20 min-h-screen">
      <div className="max-w-6xl mx-auto px-6">
        <h2 className="text-4xl font-bold text-white text-center mb-16">
          Basic Animations1
        </h2>

        {/* Simple Tweens */}
        <div className="mb-16 bg-white bg-opacity-10 rounded-2xl p-8 backdrop-blur-sm">
          <h3 className="text-2xl font-semibold text-white mb-6">
            Simple Tweens
          </h3>
          <div
            className="flex justify-center items-center gap-8 mb-8 min-h-[200px] bg-black bg-opacity-20 rounded-xl p-8 cursor-pointer"
            onClick={playBasicTweens}
          >
            <div
              ref={(el) => addToTweenRefs(el, 0)}
              className="w-20 h-20 bg-green-400 rounded-xl flex items-center justify-center text-black font-bold"
            >
              Scale
            </div>
            <div
              ref={(el) => addToTweenRefs(el, 1)}
              className="w-20 h-20 bg-green-400 rounded-xl flex items-center justify-center text-black font-bold"
            >
              Rotate
            </div>
            <div
              ref={(el) => addToTweenRefs(el, 2)}
              className="w-20 h-20 bg-green-400 rounded-xl flex items-center justify-center text-black font-bold"
            >
              Move
            </div>
          </div>
        </div>

        {/* Timeline Example */}
        <div className="mb-16 bg-white bg-opacity-10 rounded-2xl p-8 backdrop-blur-sm">
          <h3 className="text-2xl font-semibold text-white mb-6">
            Timeline Sequence
          </h3>
          <div
            className="flex justify-center items-center gap-8 mb-8 min-h-[200px] bg-black bg-opacity-20 rounded-xl p-8 cursor-pointer"
            onClick={playTimeline}
          >
            {[1, 2, 3, 4].map((num, index) => (
              <div
                key={num}
                ref={(el) => addToTimelineRefs(el, index)}
                className="w-20 h-20 bg-red-400 rounded-xl flex items-center justify-center text-white font-bold text-2xl"
              >
                {num}
              </div>
            ))}
          </div>
        </div>

        {/* Text Animation */}
        <div className="bg-white bg-opacity-10 rounded-2xl p-8 backdrop-blur-sm">
          <h3 className="text-2xl font-semibold text-white mb-6">
            Text Animation
