"use client";

import { useEffect, useRef } from "react";
import { gsap } from "gsap";

const Hero = () => {
  const heroRef = useRef<HTMLDivElement>(null);
  const titleRef = useRef<HTMLHeadingElement>(null);
  const subtitleRef = useRef<HTMLParagraphElement>(null);
  const floatingBoxesRef = useRef<HTMLDivElement[]>([]);

  useEffect(() => {
    const ctx = gsap.context(() => {
      // Hero title animation
      if (titleRef.current) {
        gsap.fromTo(
          titleRef.current,
          { scale: 0, rotation: 180, opacity: 0 },
          {
            scale: 1,
            rotation: 0,
            opacity: 1,
            duration: 1.5,
            ease: "back.out(1.7)",
            delay: 1,
          }
        );
      }

      // Subtitle animation
      if (subtitleRef.current) {
        gsap.fromTo(
          subtitleRef.current,
          { y: 50, opacity: 0 },
          {
            y: 0,
            opacity: 1,
            duration: 1,
            ease: "power2.out",
            delay: 1.5,
          }
        );
      }

      // Floating boxes animation
      // Predefined animation values for consistency
      const animationValues = [
        {
          x: 200,
          y: 150,
          rotation: 45,
          scale: 0.8,
          moveY: 30,
          moveX: 20,
          rotateBy: 15,
          duration: 4,
          delay: 0,
        },
        {
          x: 800,
          y: 100,
          rotation: 120,
          scale: 1.2,
          moveY: -40,
          moveX: -25,
          rotateBy: -20,
          duration: 3.5,
          delay: 0.5,
        },
        {
          x: 300,
          y: 400,
          rotation: 270,
          scale: 0.6,
          moveY: 50,
          moveX: 15,
          rotateBy: 25,
          duration: 5,
          delay: 1,
        },
        {
          x: 700,
          y: 500,
          rotation: 180,
          scale: 1.0,
          moveY: -30,
          moveX: -20,
          rotateBy: -10,
          duration: 3,
          delay: 1.5,
        },
        {
          x: 500,
          y: 200,
          rotation: 90,
          scale: 0.9,
          moveY: 40,
          moveX: 30,
          rotateBy: 20,
          duration: 4.5,
          delay: 0.8,
        },
        {
          x: 400,
          y: 350,
          rotation: 315,
          scale: 0.7,
          moveY: -20,
          moveX: 25,
          rotateBy: -15,
          duration: 3.8,
          delay: 1.2,
        },
      ];

      floatingBoxesRef.current.forEach((box, index) => {
        if (box && animationValues[index]) {
          const values = animationValues[index];

          // Initial position
          gsap.set(box, {
            x: values.x,
            y: values.y,
            rotation: values.rotation,
            scale: values.scale,
          });

          // Floating animation
          gsap.to(box, {
            y: `+=${values.moveY}`,
            x: `+=${values.moveX}`,
            rotation: `+=${values.rotateBy}`,
            duration: values.duration,
            ease: "sine.inOut",
            repeat: -1,
            yoyo: true,
            delay: index * 0.3,
          });

          // Continuous floating
          gsap.to(box, {
            y: "+=20",
            duration: 2,
            ease: "sine.inOut",
            repeat: -1,
            yoyo: true,
            delay: values.delay,
          });
        }
      });
    }, heroRef);

    return () => ctx.revert();
  }, []);

  const addToRefs = (el: HTMLDivElement | null, index: number) => {
    if (el) {
      floatingBoxesRef.current[index] = el;
    }
  };

  return (
    <section
      id="hero"
      ref={heroRef}
      className="relative h-screen flex items-center justify-center text-center overflow-hidden"
    >
      {/* Floating background elements */}
      <div className="absolute inset-0 pointer-events-none">
        {[
          { left: 15, top: 20 },
          { left: 85, top: 10 },
          { left: 25, top: 70 },
          { left: 75, top: 80 },
          { left: 60, top: 30 },
          { left: 40, top: 60 },
        ].map((position, index) => (
          <div
            key={index}
            ref={(el) => addToRefs(el, index)}
            className="absolute w-16 h-16 bg-white bg-opacity-20 rounded-xl backdrop-blur-sm"
            style={{
              left: `${position.left}%`,
              top: `${position.top}%`,
            }}
          />
        ))}
      </div>

      {/* Hero content */}
      <div className="relative z-10 max-w-4xl mx-auto px-6">
        <h1
          ref={titleRef}
          className="text-6xl md:text-8xl font-bold text-white mb-6 drop-shadow-lg"
        >
          Awesome GSAP
        </h1>
        <p
          ref={subtitleRef}
          className="text-xl md:text-2xl text-white text-opacity-90 mb-8"
        >
          React + Next.js Examples
        </p>

        {/* Animated scroll indicator */}
        <div className="absolute bottom-10 left-1/2 transform -translate-x-1/2">
          <div className="w-6 h-10 border-2 border-white border-opacity-50 rounded-full flex justify-center">
            <div className="w-1 h-3 bg-white bg-opacity-70 rounded-full mt-2 animate-bounce"></div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default Hero;

"use client";

import { useRef } from "react";
import { gsap } from "gsap";

export default function HoverInteractions() {
  const hoverBoxRef = useRef<HTMLDivElement>(null);
  const clickBoxRef = useRef<HTMLDivElement>(null);

  const handleHoverEnter = () => {
    if (hoverBoxRef.current) {
      gsap.to(hoverBoxRef.current, {
        scale: 1.2,
        rotation: 15,
        backgroundColor: "#ff6b6b",
        duration: 0.3,
        ease: "back.out(1.7)",
      });
    }
  };

  const handleHoverLeave = () => {
    if (hoverBoxRef.current) {
      gsap.to(hoverBoxRef.current, {
        scale: 1,
        rotation: 0,
        backgroundColor: "#4ecdc4",
        duration: 0.3,
        ease: "power2.out",
      });
    }
  };

  const handleClick = () => {
    if (clickBoxRef.current) {
      gsap.to(clickBoxRef.current, {
        scale: 0.8,
        duration: 0.1,
        ease: "power2.out",
        yoyo: true,
        repeat: 1,
        onComplete: () => {
          gsap.to(clickBoxRef.current, {
            rotation: "+=360",
            backgroundColor: "#00ff88",
            duration: 0.6,
            ease: "power2.out",
            onComplete: () => {
              gsap.to(clickBoxRef.current, {
                backgroundColor: "#4ecdc4",
                duration: 0.3,
                delay: 0.2,
              });
            },
          });
        },
      });
    }
  };

  const runAnimation = () => {
    // Demo both interactions
    handleHoverEnter();
    setTimeout(() => {
      handleHoverLeave();
      setTimeout(() => {
        handleClick();
      }, 500);
    }, 1000);
  };

  return (
    <div className="flex gap-6 justify-center items-center">
      <div
        ref={hoverBoxRef}
        className="w-24 h-24 bg-teal-400 rounded-lg flex items-center justify-center text-gray-800 font-bold cursor-pointer select-none shadow-lg"
        onMouseEnter={handleHoverEnter}
        onMouseLeave={handleHoverLeave}
        onClick={runAnimation}
      >
        Hover Me
      </div>
      <div
        ref={clickBoxRef}
        className="w-24 h-24 bg-teal-400 rounded-lg flex items-center justify-center text-gray-800 font-bold cursor-pointer select-none shadow-lg hover:scale-105 transition-transform"
        onClick={handleClick}
      >
        Click Me
      </div>
    </div>
  );
}

"use client";

import { useRef, useState } from "react";
import { gsap } from "gsap";

const InteractiveAnimations = () => {
  const hoverBox1Ref = useRef<HTMLDivElement>(null);
  const hoverBox2Ref = useRef<HTMLDivElement>(null);
  const mouseAreaRef = useRef<HTMLDivElement>(null);
  const followerRef = useRef<HTMLDivElement>(null);
  const [trails, setTrails] = useState<
    Array<{ id: number; x: number; y: number }>
  >([]);
  const trailIdRef = useRef(0);

  const handleHoverEnter1 = () => {
    if (hoverBox1Ref.current) {
      gsap.to(hoverBox1Ref.current, {
        scale: 1.2,
        rotation: 15,
        backgroundColor: "#EF4444",
        duration: 0.3,
        ease: "back.out(1.7)",
      });
    }
  };

  const handleHoverLeave1 = () => {
    if (hoverBox1Ref.current) {
      gsap.to(hoverBox1Ref.current, {
        scale: 1,
        rotation: 0,
        backgroundColor: "#06B6D4",
        duration: 0.3,
        ease: "power2.out",
      });
    }
  };

  const handleClick2 = () => {
    if (hoverBox2Ref.current) {
      gsap.to(hoverBox2Ref.current, {
        scale: 0.8,
        duration: 0.1,
        ease: "power2.out",
        yoyo: true,
        repeat: 1,
        onComplete: () => {
          gsap.to(hoverBox2Ref.current, {
            rotation: "+=360",
            duration: 0.5,
            ease: "power2.out",
          });
        },
      });
    }
  };

  const handleHoverEnter2 = () => {
    if (hoverBox2Ref.current) {
      gsap.to(hoverBox2Ref.current, {
        scale: 1.1,
        duration: 0.3,
        ease: "power2.out",
      });
    }
  };

  const handleHoverLeave2 = () => {
    if (hoverBox2Ref.current) {
      gsap.to(hoverBox2Ref.current, {
        scale: 1,
        duration: 0.3,
        ease: "power2.out",
      });
    }
  };

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    if (mouseAreaRef.current && followerRef.current) {
      const rect = mouseAreaRef.current.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      gsap.to(followerRef.current, {
        x: x - 10,
        y: y - 10,
        duration: 0.3,
        ease: "power2.out",
      });

      // Create trail effect
      const newTrail = { id: ++trailIdRef.current, x, y };
      setTrails((prev) => [...prev.slice(-10), newTrail]);

      // Remove trail after animation
      setTimeout(() => {
        setTrails((prev) => prev.filter((trail) => trail.id !== newTrail.id));
      }, 1000);
    }
  };

  const handleMouseEnterArea = () => {
    if (followerRef.current) {
      gsap.to(followerRef.current, {
        scale: 1,
        opacity: 1,
        duration: 0.3,
        ease: "power2.out",
      });
    }
  };

  const handleMouseLeaveArea = () => {
    if (followerRef.current) {
      gsap.to(followerRef.current, {
        scale: 0,
        opacity: 0,
        duration: 0.3,
        ease: "power2.out",
      });
    }
  };

  return (
    <section id="interactive" className="py-20 min-h-screen">
      <div className="max-w-6xl mx-auto px-6">
        <h2 className="text-4xl font-bold text-white text-center mb-16">
          Interactive Animations
        </h2>

        {/* Hover Effects */}
        <div className="mb-16 bg-white bg-opacity-10 rounded-2xl p-8 backdrop-blur-sm">
          <h3 className="text-2xl font-semibold text-white mb-6">
            Hover Effects
          </h3>
          <div className="flex justify-center items-center gap-8 mb-8 min-h-[200px] bg-black bg-opacity-20 rounded-xl p-8">
            <div
              ref={hoverBox1Ref}
              onMouseEnter={handleHoverEnter1}
              onMouseLeave={handleHoverLeave1}
              className="w-24 h-24 bg-cyan-400 rounded-xl flex items-center justify-center text-black font-bold cursor-pointer select-none"
            >
              Hover Me
            </div>
            <div
              ref={hoverBox2Ref}
              onClick={handleClick2}
              onMouseEnter={handleHoverEnter2}
              onMouseLeave={handleHoverLeave2}
              className="w-24 h-24 bg-cyan-400 rounded-xl flex items-center justify-center text-black font-bold cursor-pointer select-none"
            >
              Click Me
            </div>
          </div>
        </div>

        {/* Mouse Follow */}
        <div className="bg-white bg-opacity-10 rounded-2xl p-8 backdrop-blur-sm">
          <h3 className="text-2xl font-semibold text-white mb-6">
            Mouse Follow
          </h3>
          <div
            ref={mouseAreaRef}
            onMouseMove={handleMouseMove}
            onMouseEnter={handleMouseEnterArea}
            onMouseLeave={handleMouseLeaveArea}
            className="relative min-h-[300px] bg-black bg-opacity-20 rounded-xl p-8 cursor-none overflow-hidden"
          >
            {/* Follower */}
            <div
              ref={followerRef}
              className="absolute w-5 h-5 bg-green-400 rounded-full pointer-events-none z-10"
              style={{ scale: 0, opacity: 0 }}
            />

            {/* Trail dots */}
            {trails.map((trail) => (
              <div
                key={trail.id}
                className="absolute w-1 h-1 bg-green-400 rounded-full pointer-events-none animate-ping"
                style={{
                  left: trail.x - 2,
                  top: trail.y - 2,
                }}
              />
            ))}

            <p className="text-white text-center mt-32 pointer-events-none">
              Move your mouse in this area
            </p>
          </div>
        </div>
      </div>
    </section>
  );
};

export default InteractiveAnimations;

