"use client";

import { useRef, useState } from "react";
import { gsap } from "gsap";

export default function MouseFollow() {
  const areaRef = useRef<HTMLDivElement>(null);
  const followerRef = useRef<HTMLDivElement>(null);
  const [isActive, setIsActive] = useState(false);

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    if (followerRef.current && areaRef.current) {
      const rect = areaRef.current.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      gsap.to(followerRef.current, {
        x: x - 10,
        y: y - 10,
        duration: 0.3,
        ease: "power2.out",
      });
    }
  };

  const handleMouseEnter = () => {
    setIsActive(true);
    if (followerRef.current) {
      gsap.to(followerRef.current, {
        scale: 1,
        opacity: 1,
        duration: 0.3,
        ease: "back.out(1.7)",
      });
    }
  };

  const handleMouseLeave = () => {
    setIsActive(false);
    if (followerRef.current) {
      gsap.to(followerRef.current, {
        scale: 0,
        opacity: 0,
        duration: 0.3,
        ease: "power2.out",
      });
    }
  };

  const runAnimation = () => {
    if (followerRef.current && areaRef.current) {
      // Demo animation - simulate mouse movement
      const centerX = areaRef.current.offsetWidth / 2;
      const centerY = areaRef.current.offsetHeight / 2;

      // Show follower
      gsap.set(followerRef.current, { scale: 1, opacity: 1 });

      // Animate in a circle
      const tl = gsap.timeline();

      for (let i = 0; i <= 8; i++) {
        const angle = (i / 8) * Math.PI * 2;
        const x = centerX + Math.cos(angle) * 40 - 10;
        const y = centerY + Math.sin(angle) * 40 - 10;

        tl.to(followerRef.current, {
          x,
          y,
          duration: 0.3,
          ease: "power2.out",
        });
      }

      // Hide follower
      tl.to(followerRef.current, {
        scale: 0,
        opacity: 0,
        duration: 0.3,
        ease: "power2.out",
      });
    }
  };

  return (
    <div
      ref={areaRef}
      className={`relative min-h-[150px] bg-black/20 rounded-xl flex items-center justify-center text-white/70 text-lg select-none ${
        isActive ? "cursor-none" : "cursor-pointer"
      }`}
      onMouseMove={handleMouseMove}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
      onClick={runAnimation}
    >
      <div
        ref={followerRef}
        className="absolute w-5 h-5 bg-green-400 rounded-full pointer-events-none z-10 opacity-0 scale-0 shadow-lg"
        style={{ transform: "translate(-50%, -50%)" }}
      />
      <p>Move your mouse here</p>
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";
import { gsap } from "gsap";
import { ScrollToPlugin } from "gsap/ScrollToPlugin";

// Register GSAP plugins
if (typeof window !== "undefined") {
  gsap.registerPlugin(ScrollToPlugin);
}

const Navigation = () => {
  const navRef = useRef<HTMLElement>(null);
  const titleRef = useRef<HTMLHeadingElement>(null);
  const menuItemsRef = useRef<HTMLButtonElement[]>([]);
  const mobileButtonRef = useRef<HTMLButtonElement>(null);
  const lastScrollY = useRef(0);

  useEffect(() => {
    const handleScroll = () => {
      const currentScrollY = window.scrollY;

      // Determine navbar visibility based on scroll direction
      const scrollingDown =
        currentScrollY > lastScrollY.current && currentScrollY > 100;
      const scrollingUp = currentScrollY < lastScrollY.current;

      if (navRef.current) {
        if (scrollingDown) {
          // Hide navbar when scrolling down
          gsap.to(navRef.current, {
            y: "-100%",
            duration: 0.3,
            ease: "power2.out",
          });
        } else if (scrollingUp || currentScrollY <= 100) {
          // Show navbar when scrolling up or at top
          gsap.to(navRef.current, {
            y: "0%",
            duration: 0.3,
            ease: "power2.out",
          });
        }
      }

      lastScrollY.current = currentScrollY;
    };

    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  useEffect(() => {
    // Initial animation
    if (navRef.current) {
      gsap.fromTo(
        navRef.current,
        { y: -100, opacity: 0 },
        { y: 0, opacity: 1, duration: 1, ease: "power2.out", delay: 0.5 }
      );
    }
  }, []);

  const scrollToSection = (sectionId: string) => {
    const element = document.getElementById(sectionId);
    if (element) {
      // Kill any existing scroll animations to prevent conflicts
      gsap.killTweensOf(window);

      gsap.to(window, {
        duration: 1.0,
        scrollTo: {
          y: element,
          offsetY: 80,
        },
        ease: "power2.out",
      });
    }
  };

  const navItems = [
    { id: "basic", label: "Basic" },
    { id: "scroll", label: "ScrollTrigger" },
    { id: "interactive", label: "Interactive" },
    { id: "advanced", label: "Advanced" },
    { id: "honor", label: "Honor", isExternal: true, href: "/honor" },
    { id: "folio", label: "Folio", isExternal: true, href: "/folio" },
  ];

  return (
    <nav
      ref={navRef}
      className="fixed top-0 w-full z-50 transition-all duration-300"
      style={{
        backgroundColor: "rgba(255, 255, 255, 0.1)",
        backdropFilter: "blur(5px)",
      }}
    >
      <div className="max-w-6xl mx-auto px-6 py-4">
        <div className="flex justify-between items-center">
          <h1
            ref={titleRef}
            className="text-2xl font-bold text-white cursor-pointer hover:text-green-400 transition-colors duration-200 active:scale-95 transform"
            onClick={() => scrollToSection("hero")}
          >
            GSAP Examples
          </h1>

          <ul className="hidden md:flex space-x-8">
            {navItems.map((item, index) => (
              <li key={item.id}>
                {item.isExternal ? (
                  <a
                    href={item.href}
                    className="text-white hover:text-green-400 transition-colors duration-200 font-medium cursor-pointer active:scale-95 transform"
                  >
                    {item.label}
                  </a>
                ) : (
                  <button
                    ref={(el) => {
                      if (el) menuItemsRef.current[index] = el;
                    }}
                    onClick={() => scrollToSection(item.id)}
                    className="text-white hover:text-green-400 transition-colors duration-200 font-medium cursor-pointer active:scale-95 transform"
                  >
                    {item.label}
                  </button>
                )}
              </li>
            ))}
          </ul>

          {/* Mobile menu button */}
          <button
            ref={mobileButtonRef}
            className="md:hidden text-white cursor-pointer hover:text-green-400 transition-colors duration-200 active:scale-95 transform"
          >
            <svg
              className="w-6 h-6"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M4 6h16M4 12h16M4 18h16"
              />
            </svg>
          </button>
        </div>
      </div>
    </nav>
  );
};

export default Navigation;

"use client";

import { useRef, useEffect } from "react";
import { gsap } from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

export default function ParallaxEffects() {
  const containerRef = useRef<HTMLDivElement>(null);
  const bgRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    gsap.registerPlugin(ScrollTrigger);

    if (bgRef.current && contentRef.current && containerRef.current) {
      // Parallax background animation
      const bgAnimation = gsap.to(bgRef.current, {
        yPercent: -50,
        ease: "none",
        scrollTrigger: {
          trigger: containerRef.current,
          start: "top bottom",
          end: "bottom top",
          scrub: true,
        },
      });

      // Content fade in animation
      const contentAnimation = gsap.fromTo(
        contentRef.current,
        {
          y: 50,
          opacity: 0,
        },
        {
          y: 0,
          opacity: 1,
          duration: 1,
          ease: "power2.out",
          scrollTrigger: {
            trigger: contentRef.current,
            start: "top 70%",
            toggleActions: "play none none reverse",
          },
        }
      );

      return () => {
        bgAnimation.kill();
        contentAnimation.kill();
        ScrollTrigger.getAll().forEach((trigger) => {
          if (trigger && typeof trigger.kill === "function") {
            trigger.kill();
          }
        });
      };
    }
  }, []);

  const runAnimation = () => {
    if (bgRef.current && contentRef.current) {
      // Manual demo animation
      const tl = gsap.timeline();

      tl.to(bgRef.current, {
        y: -20,
        duration: 1,
        ease: "power2.out",
      })
        .fromTo(
          contentRef.current,
          {
            y: 30,
            opacity: 0.5,
          },
          {
            y: 0,
            opacity: 1,
            duration: 0.8,
            ease: "power2.out",
          },
          "-=0.5"
        )
        .to([bgRef.current, contentRef.current], {
          y: 0,
          opacity: 1,
          duration: 0.8,
          ease: "power2.out",
        });
    }
  };

  return (
    <div
      ref={containerRef}
      className="relative h-40 w-full overflow-hidden rounded-xl cursor-pointer"
      onClick={runAnimation}
    >
      <div
        ref={bgRef}
        className="absolute inset-0 bg-gradient-to-br from-red-400 to-blue-400 opacity-70 transform -translate-y-4"
      />
      <div
        ref={contentRef}
        className="relative z-10 h-full flex flex-col items-center justify-center text-white text-center"
      >
        <h4 className="text-xl font-bold mb-2">Parallax Effect</h4>
        <p className="text-sm">Background moves differently</p>
      </div>
    </div>
  );
}

'use client'

import { useEffect, useRef } from 'react'
import { gsap } from 'gsap'
import { ScrollTrigger } from 'gsap/ScrollTrigger'

// Register ScrollTrigger plugin
if (typeof window !== 'undefined') {
  gsap.registerPlugin(ScrollTrigger)
}

const ScrollAnimations = () => {
  const sectionRef = useRef<HTMLDivElement>(null)
  const scrollBoxRef = useRef<HTMLDivElement>(null)
  const parallaxBgRef = useRef<HTMLDivElement>(null)
  const parallaxContentRef = useRef<HTMLDivElement>(null)
  const cardsRef = useRef<HTMLDivElement[]>([])

  const addToCardsRefs = (el: HTMLDivElement | null, index: number) => {
    if (el) {
      cardsRef.current[index] = el
    }
  }

  useEffect(() => {
    const ctx = gsap.context(() => {
      // Scroll-triggered box animation
      if (scrollBoxRef.current) {
        gsap.fromTo(scrollBoxRef.current, {
          scale: 0.5,
          rotation: 0,
          backgroundColor: '#EF4444'
        }, {
          scale: 1.2,
          rotation: 360,
          backgroundColor: '#10B981',
          duration: 1,
          ease: 'back.out(1.7)',
          scrollTrigger: {
            trigger: scrollBoxRef.current,
            start: 'top 80%',
            end: 'bottom 20%',
            scrub: 1,
            toggleActions: 'play none none reverse'
          }
        })
      }

      // Parallax background animation
      if (parallaxBgRef.current) {
        gsap.to(parallaxBgRef.current, {
          yPercent: -50,
          ease: 'none',
          scrollTrigger: {
            trigger: parallaxBgRef.current.parentElement,
            start: 'top bottom',
            end: 'bottom top',
            scrub: true
          }
        })
      }

      // Parallax content animation
      if (parallaxContentRef.current) {
        gsap.fromTo(parallaxContentRef.current, {
          y: 100,
          opacity: 0
        }, {
          y: 0,
          opacity: 1,
          duration: 1,
          ease: 'power2.out',
          scrollTrigger: {
            trigger: parallaxContentRef.current,
            start: 'top 70%',
            toggleActions: 'play none none reverse'
          }
        })
      }

      // Card reveal animations
      cardsRef.current.forEach((card, index) => {
        if (card) {
          gsap.fromTo(card, {
            y: 100,
            opacity: 0,
            scale: 0.8
          }, {
            y: 0,
            opacity: 1,
            scale: 1,
            duration: 0.8,
            ease: 'back.out(1.7)',
            scrollTrigger: {
              trigger: card,
              start: 'top 80%',
              toggleActions: 'play none none reverse'
            },
            delay: index * 0.2
          })
        }
      })

      // Section title animation
      const sectionTitle = sectionRef.current?.querySelector('h2')
      if (sectionTitle) {
        gsap.fromTo(sectionTitle, {
          y: 50,
          opacity: 0
        }, {
          y: 0,
          opacity: 1,
          duration: 1,
          ease: 'power2.out',
          scrollTrigger: {
            trigger: sectionTitle,
            start: 'top 80%',
            toggleActions: 'play none none reverse'
          }
        })
      }
    }, sectionRef)

    return () => ctx.revert()
  }, [])

  return (
    <section 
      id="scroll" 
      ref={sectionRef}
      className="py-20 min-h-screen bg-gradient-to-br from-purple-800 via-blue-800 to-purple-600"
    >
      <div className="max-w-6xl mx-auto px-6">
        <h2 className="text-4xl font-bold text-white text-center mb-16">
          ScrollTrigger Animations
        </h2>

        {/* Scroll-triggered box */}
        <div className="mb-16 bg-white bg-opacity-10 rounded-2xl p-8 backdrop-blur-sm">
          <h3 className="text-2xl font-semibold text-white mb-6">Scroll to Animate</h3>
          <div className="flex justify-center items-center min-h-[400px] bg-black bg-opacity-20 rounded-xl p-8">
            <div 
              ref={scrollBoxRef}
              className="w-48 h-48 rounded-2xl flex items-center justify-center font-bold text-white text-xl"
              style={{ backgroundColor: '#EF4444' }}
            >
              Scroll to animate
            </div>
          </div>
        </div>

        {/* Parallax container */}
        <div className="mb-16 relative h-96 overflow-hidden rounded-2xl">
          <div 
            ref={parallaxBgRef}
            className="absolute inset-0 bg-gradient-to-r from-pink-500 to-yellow-500 opacity-30"
            style={{ height: '120%', top: '-10%' }}
          />
          <div 
            ref={parallaxContentRef}
            className="relative z-10 h-full flex flex-col items-center justify-center text-center text-white"
          >
            <h3 className="text-3xl font-bold mb-4">Parallax Effect</h3>
            <p className="text-lg">This background moves at a different speed</p>
          </div>
        </div>

        {/* Reveal cards */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          {[1, 2, 3, 4].map((num, index) => (
            <div
              key={num}
              ref={(el) => addToCardsRefs(el, index)}
              className="h-48 bg-white bg-opacity-10 rounded-2xl flex items-center justify-center text-white text-2xl font-bold backdrop-blur-sm hover:scale-105 transition-transform cursor-pointer"
            >
              Card {num}
            </div>
          ))}
        </div>
      </div>
    </section>
  )
}

export default ScrollAnimations

