"use client";

import { useRef, useEffect } from "react";
import { gsap } from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

export default function ScrollTriggerModule() {
  const scrollBoxRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    gsap.registerPlugin(ScrollTrigger);

    if (scrollBoxRef.current && triggerRef.current) {
      const animation = gsap.fromTo(
        scrollBoxRef.current,
        {
          scale: 0.5,
          rotation: 0,
          backgroundColor: "#ff6b6b",
        },
        {
          scale: 1.2,
          rotation: 360,
          backgroundColor: "#00ff88",
          duration: 1,
          ease: "back.out(1.7)",
          scrollTrigger: {
            trigger: triggerRef.current,
            start: "top 80%",
            end: "bottom 20%",
            scrub: 1,
            toggleActions: "play none none reverse",
          },
        }
      );

      return () => {
        animation.kill();
        ScrollTrigger.getAll().forEach((trigger) => {
          if (trigger && typeof trigger.kill === "function") {
            trigger.kill();
          }
        });
      };
    }
  }, []);

  const runAnimation = () => {
    if (scrollBoxRef.current) {
      // Manual trigger animation for demo
      gsap.fromTo(
        scrollBoxRef.current,
        {
          scale: 0.5,
          rotation: 0,
          backgroundColor: "#ff6b6b",
        },
        {
          scale: 1.2,
          rotation: 360,
          backgroundColor: "#00ff88",
          duration: 1,
          ease: "back.out(1.7)",
          yoyo: true,
          repeat: 1,
        }
      );
    }
  };

  return (
    <div
      ref={triggerRef}
      className="flex justify-center items-center min-h-[150px]"
    >
      <div
        ref={scrollBoxRef}
        className="w-32 h-32 bg-red-400 rounded-2xl flex items-center justify-center text-white font-bold transition-colors cursor-pointer"
        onClick={runAnimation}
      >
        Scroll to animate
      </div>
    </div>
  );
}

"use client";

import { useRef } from "react";
import { gsap } from "gsap";

export default function ShapeMorphing() {
  const morphShapeRef = useRef<SVGPathElement>(null);

  const runAnimation = () => {
    if (morphShapeRef.current) {
      const shapes = [
        "M100,50 L150,150 L50,150 Z", // Triangle
        "M50,100 Q100,50 150,100 Q100,150 50,100", // Diamond-like
        "M100,50 A50,50 0 1,1 100,150 A50,50 0 1,1 100,50", // Circle
        "M50,75 L150,75 L150,125 L50,125 Z", // Rectangle
        "M100,50 L150,150 L50,150 Z", // Back to triangle
      ];

      const colors = ["#00ff88", "#ff6b6b", "#4ecdc4", "#8B5CF6", "#00ff88"];

      const tl = gsap.timeline();

      shapes.forEach((shape, index) => {
        tl.to(
          morphShapeRef.current,
          {
            attr: { d: shape },
            fill: colors[index],
            duration: 1,
            ease: "power2.inOut",
          },
          index * 1.2
        );
      });
    }
  };

  return (
    <div className="flex justify-center items-center p-4">
      <svg
        width="200"
        height="200"
        viewBox="0 0 200 200"
        className="cursor-pointer"
        onClick={runAnimation}
      >
        <path
          ref={morphShapeRef}
          className="morph-shape"
          d="M100,50 L150,150 L50,150 Z"
          fill="#00ff88"
          style={{
            filter: "drop-shadow(0 4px 15px rgba(0, 255, 136, 0.3))",
            transformOrigin: "center",
          }}
        />
      </svg>
    </div>
  );
}

"use client";

import { useRef } from "react";
import { gsap } from "gsap";
import { MotionPathPlugin } from "gsap/MotionPathPlugin";

export default function SvgPath() {
  const pathFollowerRef = useRef<SVGCircleElement>(null);
  const motionPathRef = useRef<SVGPathElement>(null);

  const runAnimation = () => {
    if (pathFollowerRef.current && motionPathRef.current) {
      // Check if MotionPathPlugin is available
      if (typeof MotionPathPlugin !== "undefined") {
        gsap.registerPlugin(MotionPathPlugin);

        // Reset position
        gsap.set(pathFollowerRef.current, {
          motionPath: { path: motionPathRef.current, start: 0 },
        });

        // Animate along path
        gsap.to(pathFollowerRef.current, {
          motionPath: {
            path: motionPathRef.current,
            align: motionPathRef.current,
            alignOrigin: [0.5, 0.5],
            autoRotate: true,
          },
          duration: 3,
          ease: "power2.inOut",
          repeat: 1,
          yoyo: true,
        });

        // Add scale animation
        gsap.to(pathFollowerRef.current, {
          scale: 1.5,
          duration: 1.5,
          ease: "sine.inOut",
          repeat: 1,
          yoyo: true,
        });
      } else {
        // Fallback animation without MotionPathPlugin
        gsap.to(pathFollowerRef.current, {
          rotation: 360,
          transformOrigin: "150px 100px",
          duration: 3,
          ease: "power2.inOut",
          repeat: 1,
          yoyo: true,
        });

        gsap.to(pathFollowerRef.current, {
          scale: 1.5,
          duration: 1.5,
          ease: "sine.inOut",
          repeat: 1,
          yoyo: true,
        });
      }
    }
  };

  return (
    <div className="flex justify-center items-center p-4">
      <svg
        width="300"
        height="200"
        viewBox="0 0 300 200"
        className="cursor-pointer"
        onClick={runAnimation}
      >
        <path
          ref={motionPathRef}
          className="motion-path"
          d="M50,100 Q150,50 250,100"
          stroke="#00ff88"
          strokeWidth="2"
          fill="none"
          strokeDasharray="5,5"
        >
          <animate
            attributeName="stroke-dashoffset"
            values="0;-10"
            dur="2s"
            repeatCount="indefinite"
          />
        </path>
        <circle
          ref={pathFollowerRef}
          className="path-follower"
          r="8"
          fill="#ff6b6b"
          style={{ filter: "drop-shadow(0 0 10px rgba(255, 107, 107, 0.5))" }}
        />
      </svg>
    </div>
  );
}

"use client";

import { useRef, useState } from "react";
import { gsap } from "gsap";

export default function TextAnimations() {
  const textRef = useRef<HTMLHeadingElement>(null);
  const [isAnimating, setIsAnimating] = useState(false);

  const runAnimation = () => {
    if (isAnimating || !textRef.current) return;

    setIsAnimating(true);
    const text = "Hello GSAP World!";
    const chars = text.split("");

    textRef.current.innerHTML = chars
      .map((char) =>
        char === " " ? "&nbsp;" : `<span class="inline-block">${char}</span>`
      )
      .join("");

    const charElements = textRef.current.querySelectorAll("span");

    gsap.fromTo(
      charElements,
      {
        opacity: 0,
        y: 50,
        rotation: 180,
        scale: 0,
      },
      {
        opacity: 1,
        y: 0,
        rotation: 0,
        scale: 1,
        duration: 0.8,
        ease: "back.out(1.7)",
        stagger: 0.05,
        onComplete: () => {
          // Color wave animation
          gsap.to(charElements, {
            color: "#00ff88",
            duration: 0.3,
            stagger: 0.05,
            yoyo: true,
            repeat: 1,
            onComplete: () => {
              // Bounce effect
              gsap.to(charElements, {
                y: -10,
                duration: 0.2,
                stagger: 0.03,
                yoyo: true,
                repeat: 1,
                ease: "power2.out",
                onComplete: () => setIsAnimating(false),
              });
            },
          });
        },
      }
    );
  };

  return (
    <div className="text-center">
      <h2
        ref={textRef}
        className={`text-4xl font-bold text-white cursor-pointer transition-colors ${
          isAnimating ? "pointer-events-none" : "hover:text-green-400"
        }`}
        onClick={runAnimation}
      >
        Hello GSAP World!
      </h2>
    </div>
  );
}

